        info_label.setStyleSheet("color: gray; font-size: 10px; margin-top: 10px;")
        layout.addWidget(info_label)
        
        layout.addSpacing(10)
        
        # Кнопки
        btn_layout = QHBoxLayout()
        ok_btn = QPushButton("OK")
