    def search_in_choice_table(self):
        """Поиск информации в таблице Choice с выводом полной информации"""
        if not self.current_title_id:
            QMessageBox.warning(self, "Ошибка", "Сначала выберите соревнование")
            return
        
        try:
            choices_count = Choice.select().where(Choice.title_id == self.current_title_id).count()
            if choices_count == 0:
                QMessageBox.information(self, "Информация", 
                                    "Таблица Choice пуста.\n"
                                    "Сначала проведите жеребьевку квалификации.")
                return
        except Exception as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка доступа к таблице Choice: {str(e)}")
            return
        
        # Диалог поиска
        dialog = QDialog(self)
        dialog.setWindowTitle("Поиск в таблице Choice")
        dialog.setModal(True)
        dialog.setMinimumWidth(400)
        dialog.setMinimumHeight(600)
        
        layout = QVBoxLayout(dialog)
        
        # Заголовок
        title_label = QLabel("Поиск участников в жеребьевке (таблица Choice)")
        title_label.setStyleSheet("font-weight: bold; font-size: 13px; margin-bottom: 10px;")
        layout.addWidget(title_label)
        
        # Панель поиска
        search_panel = QWidget()
        search_layout = QHBoxLayout(search_panel)
        search_layout.setContentsMargins(0, 0, 0, 0)
        
        search_layout.addWidget(QLabel("Поиск:"))
        search_edit = QLineEdit()
        search_edit.setPlaceholderText("Введите ФИО, регион, тренера, группу или рейтинг...")
        search_edit.setMinimumWidth(400)
        search_layout.addWidget(search_edit)
        
        search_type_combo = QComboBox()
        search_type_combo.addItems(["Везде", "По ФИО", "По региону", "По тренеру", "По группе", "По рейтингу"])
        search_layout.addWidget(search_type_combo)
        
        search_btn = QPushButton("🔍 Найти")
        search_btn.setStyleSheet("background-color: #4CAF50; color: white; padding: 5px 15px;")
        search_layout.addWidget(search_btn)
        
        clear_btn = QPushButton("🗑️ Очистить")
        clear_btn.setStyleSheet("background-color: #FF9800; color: white; padding: 5px 15px;")
        search_layout.addWidget(clear_btn)
        
        layout.addWidget(search_panel)
        
        # Результаты поиска (краткий список)
        result_label = QLabel("Результаты поиска:")
        result_label.setStyleSheet("font-weight: bold; margin-top: 10px;")
        layout.addWidget(result_label)
        
        result_list = QListWidget()
        result_list.setStyleSheet("""
            QListWidget {
                min-height:50px;
                max-height: 100px;
                border: 1px solid #ccc;
                border-radius: 3px;
                font-size: 14px;
            }
            QListWidget::item {
                padding: 8px;
                border-bottom: 1px solid #eee;
            }
            QListWidget::item:selected {
                background-color: #4CAF50;
                color: white;
            }
        """)
        layout.addWidget(result_list)
        
        # Панель детальной информации
        detail_group = QGroupBox("📋 Полная информация об участнике")
        detail_group.setStyleSheet("""
            QGroupBox {
                font-weight: bold;
                font-size: 14px;
                border: 2px solid #2196F3;
                border-radius: 5px;
                margin-top: 10px;
            }
            QGroupBox::title {
                color: #2196F3;
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 5px 0 5px;
            }
        """)
        detail_layout = QVBoxLayout(detail_group)
        
        detail_text = QTextEdit()
        detail_text.setReadOnly(True)
        detail_text.setStyleSheet("""
            QTextEdit {
                font-family: Consolas, monospace;
                font-size: 12px;
                background-color: #f9f9f9;
                border: 1px solid #ddd;
                border-radius: 3px;
                padding: 10px;
            }
        """)
        detail_layout.addWidget(detail_text)
        
        layout.addWidget(detail_group)
        
        # Кнопки
        action_layout = QHBoxLayout()
        close_btn = QPushButton("Закрыть")
        close_btn.setStyleSheet("background-color: #f44336; color: white; padding: 5px 15px;")
        close_btn.clicked.connect(dialog.reject)
        action_layout.addStretch()
        action_layout.addWidget(close_btn)
        layout.addLayout(action_layout)
        
        # ---- Функции поиска и отображения ----
        def perform_search():
            search_text = search_edit.text().strip().lower()
            search_type = search_type_combo.currentText()
            
            if not search_text:
                QMessageBox.warning(dialog, "Ошибка", "Введите текст для поиска")
                return
            
            result_list.clear()
            detail_text.clear()
            
            try:
                all_choices = Choice.select().where((Choice.title_id == self.current_title_id) & (Choice.sex == self.current_sex))
                results = []
                for choice in all_choices:
                    player = Player.get_or_none(Player.id == choice.player_choice.id)
                    if not player:
                        continue
                    
                    match = False
                    highlight = ""
                    family_lower = choice.family.lower() if choice.family else ""
                    region_lower = choice.region.lower() if choice.region else ""
                    coach_lower = choice.coach.lower() if choice.coach else ""
                    group_lower = choice.group.lower() if choice.group else ""
                    rank_str = str(choice.rank)
                    
                    if search_type == "Везде":
                        if (search_text in family_lower or
                            search_text in region_lower or
                            search_text in coach_lower or
                            search_text in group_lower or
                            search_text == rank_str):
                            match = True
                            if search_text in family_lower:
                                highlight = f"ФИО: {choice.family}"
                            elif search_text in region_lower:
                                highlight = f"Регион: {choice.region}"
                            elif search_text in coach_lower:
                                highlight = f"Тренер: {choice.coach}"
                            elif search_text in group_lower:
                                highlight = f"Группа: {choice.group}"
                            elif search_text == rank_str:
                                highlight = f"Рейтинг: {choice.rank}"
                    elif search_type == "По ФИО":
                        if search_text in family_lower:
                            match = True
                            highlight = f"ФИО: {choice.family}"
                    elif search_type == "По региону":
                        if search_text in region_lower:
                            match = True
                            highlight = f"Регион: {choice.region}"
                    elif search_type == "По тренеру":
                        if search_text in coach_lower:
                            match = True
                            highlight = f"Тренер: {choice.coach}"
                    elif search_type == "По группе":
                        if search_text in group_lower:
                            match = True
                            highlight = f"Группа: {choice.group}"
                    elif search_type == "По рейтингу":
                        if search_text == rank_str:
                            match = True
                            highlight = f"Рейтинг: {choice.rank}"
                    
                    if match:
                        results.append({
                            'choice': choice,
                            'player': player,
                            'highlight': highlight
                        })
                
                if results:
                    for res in results:
                        choice = res['choice']
                        item_text = f"🏅 {choice.family} | {choice.region} | {choice.coach} | Рейтинг: {choice.rank}"
                        item = QListWidgetItem(item_text)
                        item.setData(Qt.UserRole, res)
                        result_list.addItem(item)
                    result_label.setText(f"Результаты поиска: найдено {len(results)} участников")
                else:
                    result_list.addItem("Ничего не найдено")
                    result_label.setText("Результаты поиска: ничего не найдено")
            except Exception as e:
                QMessageBox.critical(dialog, "Ошибка", f"Ошибка поиска: {str(e)}")
        
        def show_details():
            current_item = result_list.currentItem()
            if not current_item:
                return
            data = current_item.data(Qt.UserRole)
            if not data:
                return
            choice = data['choice']
            player = data['player']
            
            # Получаем все записи Choice для этого игрока (по player_choice)
            player_choices = Choice.select().where(
                (Choice.title_id == self.current_title_id) &
                (Choice.player_choice_id == player.id)
            ).order_by(Choice.id)
            
            details = "=" * 60 + "\n"
            details += "📋 ПОЛНАЯ ИНФОРМАЦИЯ ОБ УЧАСТНИКЕ\n"
            details += "=" * 60 + "\n\n"
            
            # Общая информация
            details += "【 ОБЩАЯ ИНФОРМАЦИЯ 】\n"
            details += f"  👤 ФИО: {choice.family}\n"
            details += f"  🏙️ Город: {player.city or '—'}\n"
            details += f"  📍 Регион: {choice.region or '—'}\n"
            details += f"  👨‍🏫 Тренер: {choice.coach or '—'}\n"
            details += f"  📊 Рейтинг: {choice.rank}\n\n"

            # --- Квалификация ---
            qual_choices = [c for c in player_choices if c.group in c.group]
            if qual_choices:
                details += "【 КВАЛИФИКАЦИЯ 】\n"
                for qc in qual_choices:
                    details += f"  🏆 Группа: {qc.group}\n"
                    details += f"  🎯 Посев в группе: {qc.posev_group}\n"
                    details += f"  🥇 Место в группе: {qc.mesto_group if qc.mesto_group else '—'}\n"
                details += "\n"
            
            # --- Полуфиналы ---
            sf_choices = [c for c in player_choices if c.semi_final in (1, 2)]
            if sf_choices:
                details += "【 ПОЛУФИНАЛЫ 】\n"
                for sc in sf_choices:
                    sf_num = "1-й полуфинал" if sc.semi_final == 1 else "2-й полуфинал"
                    details += f"  🎯 {sf_num}\n"
                    details += f"     Группа: {sc.sf_group}\n"
                    details += f"     Посев: {sc.posev_sf}\n"
                    details += f"     Место: {sc.mesto_semi_final if sc.mesto_semi_final else '—'}\n"
                details += "\n"
            
            # --- Финалы ---
            final_choices = [c for c in player_choices if c.final ]
            if final_choices:
                details += "【 ФИНАЛЫ 】\n"
                for fc in final_choices:
                    details += f"  🏆 {fc.final}\n"
                    details += f"     Посев: {fc.posev_final}\n"
                    details += f"     Место: {fc.mesto_final if fc.mesto_final else '—'}\n"
                details += "\n"
            
            # Дополнительно: если есть ещё какие-то записи
            other_choices = [c for c in player_choices if c not in qual_choices and c not in sf_choices and c not in final_choices]
            if other_choices:
                details += "【 ПРОЧИЕ ЭТАПЫ 】\n"
                for oc in other_choices:
                    details += f"  📌 {oc.stage if oc.stage else oc.group}: Посев {oc.posev_group}, Место {oc.mesto_group}\n"
                details += "\n"
            
            detail_text.setText(details)
        
        def clear_search():
            search_edit.clear()
            search_type_combo.setCurrentIndex(0)
            result_list.clear()
            detail_text.clear()
            result_label.setText("Результаты поиска:")
        
        search_btn.clicked.connect(perform_search)
        clear_btn.clicked.connect(clear_search)
        result_list.itemClicked.connect(show_details)
        result_list.itemDoubleClicked.connect(show_details)
        search_edit.returnPressed.connect(perform_search)
        
        dialog.exec_()

    def show_choice_statistics(self):
        """Показать статистику по таблице Choice"""
        if not self.current_title_id:
            QMessageBox.warning(self, "Ошибка", "Сначала выберите соревнование")
            return
        
        try:
            total_players = Choice.select().where(Choice.title_id == self.current_title_id).count()
            
            # Группировка по группам
            from collections import Counter
            groups_counter = Counter()
            regions_counter = Counter()
            
            choices = Choice.select().where(Choice.title_id == self.current_title_id)
            
            for choice in choices:
                groups_counter[choice.group] += 1
                if choice.region:
                    regions_counter[choice.region] += 1
            
            stats_text = f"📊 СТАТИСТИКА ЖЕРЕБЬЕВКИ\n"
            stats_text += "=" * 40 + "\n\n"
            stats_text += f"👥 Всего участников: {total_players}\n\n"
            
            stats_text += "🏆 РАСПРЕДЕЛЕНИЕ ПО ГРУППАМ:\n"
            for group, count in sorted(groups_counter.items()):
                stats_text += f"   • {group}: {count} чел.\n"
            
            if regions_counter:
                stats_text += "\n📍 РАСПРЕДЕЛЕНИЕ ПО РЕГИОНАМ:\n"
                for region, count in regions_counter.most_common(10):
                    stats_text += f"   • {region}: {count} чел.\n"
            
            QMessageBox.information(self, "Статистика", stats_text)
            
        except Exception as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка: {str(e)}")

    def clear_choice_table(self):
        """Очистка таблицы Choice для текущего соревнования"""
        if not self.current_title_id:
            QMessageBox.warning(self, "Ошибка", "Сначала выберите соревнование")
            return
        
        reply = QMessageBox.question(self, "Подтверждение", 
                                    "Очистить таблицу Choice для текущего соревнования?\n"
                                    "Все данные жеребьевки будут удалены!",
                                    QMessageBox.Yes | QMessageBox.No)
        
        if reply == QMessageBox.Yes:
            try:
                deleted = Choice.delete().where(Choice.title_id == self.current_title_id).execute()
                QMessageBox.information(self, "Успех", f"Удалено {deleted} записей из Choice")
                self.update_stages_info()
            except Exception as e:
                QMessageBox.critical(self, "Ошибка", f"Ошибка: {str(e)}")

    def export_choice_report(self):
        """Экспорт отчета по жеребьевке в PDF"""
        QMessageBox.information(self, "Экспорт", "Функция экспорта отчета в разработке")

    def load_matches_list(self):
        """Загрузка списка матчей для выбора"""
        self.match_combo.clear()
        
        if not self.current_title_id:
            return
        
        try:
            # Получаем все результаты для текущего соревнования
            results = Result.select().where(
                (Result.title_id == self.current_title_id) &
                (Result.sex == self.current_sex) &
                (Result.winner.is_null(True))  # Только несыгранные матчи
            ).order_by(Result.system_stage, Result.number_group, Result.round)
            
            for result in results:
                # Формируем название матча
                match_text = f"{result.system_stage} | Гр.{result.number_group} | Тур {result.tours} | {result.player1} vs {result.player2}"
                self.match_combo.addItem(match_text, result.id)
            
            if self.match_combo.count() > 0:
                self.match_combo.setCurrentIndex(0)
                self.current_stage_label.setText(f"Текущий этап: {results[0].system_stage}")
                
                # Получаем количество партий из системы
                system = System.get_or_none(System.id == results[0].system_id)
                if system:
                    score_flag = system.score_flag if system.score_flag else 5
                    self.update_scores_fields(score_flag)
                    self.current_stage_info.setText(f"Количество партий: {score_flag}")
            
            # Обновляем таблицу результатов
            self.load_results_table()
            
        except Exception as e:
            print(f"Ошибка загрузки матчей: {e}")

    def update_scores_fields(self, parties_count):
        """Обновление количества полей для ввода счетов"""
        # Активируем/деактивируем поля в зависимости от количества партий
        for i in range(7):
            self.player1_scores[i].setEnabled(i < parties_count)
            self.player2_scores[i].setEnabled(i < parties_count)
            if i >= parties_count:
                self.player1_scores[i].clear()
                self.player2_scores[i].clear()

    def on_match_selected(self, index):
        """Выбор матча из списка"""
        if index < 0:
            return
        
        result_id = self.match_combo.currentData()
        if result_id:
            self.load_match_data(result_id)

    def load_match_data(self, result_id):
        """Загрузка данных выбранного матча"""
        try:
            result = Result.get_by_id(result_id)
            
            # Заполняем информацию об игроках
            self.player1_name.setText(result.player1)
            self.player2_name.setText(result.player2)
            
            # Очищаем счета
            self.total_score.clear()
            for i in range(7):
                self.player1_scores[i].clear()
                self.player2_scores[i].clear()
            
            # Если уже есть результат, загружаем его
            if result.score_in_game:
                self.parse_and_load_scores(result.score_in_game)
            
            # Сбрасываем статусы
            self.player1_status.setCurrentIndex(0)
            self.player2_status.setCurrentIndex(0)
            
            # Получаем количество партий из системы
            system = System.get_or_none(System.id == result.system_id)
            if system:
                self.update_scores_fields(system.score_flag)
                self.current_stage_info.setText(f"Количество партий: {system.score_flag}")
            
            # Обновляем заголовок этапа
            self.current_stage_label.setText(f"Текущий этап: {result.system_stage}")
            
        except Exception as e:
            print(f"Ошибка загрузки матча: {e}")

    def parse_and_load_scores(self, score_string):
        """Парсинг строки счета и загрузка в поля"""
        try:
            # Формат: "3:1, 11:9, 9:11, 11:7, 11:5"
            parts = score_string.split(',')
            for i, part in enumerate(parts):
                if i >= 7:
                    break
                scores = part.strip().split(':')
                if len(scores) == 2:
                    self.player1_scores[i].setText(scores[0])
                    self.player2_scores[i].setText(scores[1])
        except Exception as e:
            print(f"Ошибка парсинга счета: {e}")

    def clear_result_form(self):
        """Очистка формы ввода результатов"""
        self.player1_name.clear()
        self.player2_name.clear()
        self.total_score.clear()
        for i in range(7):
            self.player1_scores[i].clear()
            self.player2_scores[i].clear()
        self.player1_status.setCurrentIndex(0)
        self.player2_status.setCurrentIndex(0)

    def load_results_table(self):
        """Загрузка таблицы результатов"""
        if not self.current_title_id:
            return
        
        try:
            results = Result.select().where((Result.title_id == self.current_title_id) & (Result.sex == self.current_sex)).order_by(
                Result.system_stage, Result.number_group, Result.tours
            )
            
            data = []
            for result in results:
                winner_text = result.winner if result.winner else ""
                score_text = result.score_in_game if result.score_in_game else ""
                
                data.append({
                    'id': result.id,
                    'stage': result.system_stage,
                    'group': result.number_group,
                    'tour': result.tours,
                    'player1': result.player1,
                    'player2': result.player2,
                    'winner': winner_text,
                    'score': score_text,
                    'points': result.score_win
                })
            
            self.results_table_model.setData(data)
            
        except Exception as e:
            print(f"Ошибка загрузки таблицы результатов: {e}")

    def select_stage_for_results(self):
        """Выбор этапа для ввода результатов"""
        group_list = ["Квалификация", "Квалификация. 1-й полуфинал","Квалификация. 2-й полуфинал"]
        
        if not self.current_title_id:
            QMessageBox.warning(self, "Ошибка", "Сначала выберите соревнование")
            return
        
        # Получаем список этапов
        stages = System.select().where((System.title_id == self.current_title_id) & (System.sex == self.current_sex)).order_by(System.id)
        
        if stages.count() == 0:
            QMessageBox.warning(self, "Ошибка", "Нет добавленных этапов")
            return
        
        # Создаем диалог выбора
        dialog = QDialog(self)
        dialog.setWindowTitle("Выбор этапа")
        dialog.setModal(True)
        dialog.setMinimumWidth(400)
        
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel("Выберите этап для ввода результатов:"))
        
        list_widget = QListWidget()
        for stage in stages:
            if stage.stage in group_list:
                # Считаем количество сыгранных матчей
                total_matches = Result.select().where(
                    (Result.title_id == self.current_title_id) &
                    (Result.sex == self.current_sex) &
                    (Result.system_stage == stage.stage)
                ).count()
                played_matches = Result.select().where(
                    (Result.title_id == self.current_title_id) &
                    (Result.sex == self.current_sex) &
                    (Result.system_stage == stage.stage) &
                    (Result.winner.is_null(False))
                ).count()
            else:
                # Считаем количество сыгранных матчей в финалах
                if stage.stage == "Одна таблица":
                    total_matches = Result.select().where(
                        (Result.title_id == self.current_title_id) &
                        (Result.sex == self.current_sex) &
                        (Result.system_stage == stage.stage)
                    ).count()
                    played_matches = Result.select().where(
                        (Result.title_id == self.current_title_id) &
                        (Result.sex == self.current_sex) &
                        (Result.system_stage == stage.stage) &
                        (Result.winner.is_null(False))
                    ).count()
                else:
                    total_matches = Result.select().where(
                        (Result.title_id == self.current_title_id) &
                        (Result.number_group == stage.stage)
                    ).count()           
                    played_matches = Result.select().where(
                        (Result.title_id == self.current_title_id) &
                        (Result.number_group == stage.stage) &
                        (Result.winner.is_null(False))
                    ).count()
            
            # Определяем тип этапа для иконки
            if stage.stage not in group_list:
                icon = "🏆"
            elif "полуфинал" in stage.stage:
                icon = "🎯"
            else:
                icon = "📋"
            
            progress = f"({played_matches}/{total_matches})" if total_matches > 0 else ""
            item_text = f"{icon} {stage.stage} | Групп: {stage.total_group} | {progress}"
            item = QListWidgetItem(item_text)
            item.setData(Qt.UserRole, stage.stage)
            
            # Подсвечиваем этапы, где есть несыгранные матчи
            if played_matches < total_matches:
                item.setForeground(QColor(255, 0, 0))
            
            list_widget.addItem(item)
        
        layout.addWidget(list_widget)
        
        btn_layout = QHBoxLayout()
        ok_btn = QPushButton("Выбрать")
        ok_btn.setStyleSheet("background-color: #4CAF50; color: white; padding: 5px;")
        ok_btn.clicked.connect(dialog.accept)
        cancel_btn = QPushButton("Отмена")
        cancel_btn.setStyleSheet("background-color: #f44336; color: white; padding: 5px;")
        cancel_btn.clicked.connect(dialog.reject)
        btn_layout.addWidget(ok_btn)
        btn_layout.addWidget(cancel_btn)
        layout.addLayout(btn_layout)
        # диалог выбора этапа
        if dialog.exec_() == QDialog.Accepted:
            selected = list_widget.currentItem()
            if selected:
                stage_name = selected.data(Qt.UserRole)
                self.current_stage = stage_name
                self.load_matches_for_stage(stage_name)
                # Обновляем таблицу результатов
                self.load_results_table_for_stage(stage_name)
                self.tab_widget.setCurrentIndex(5) 
                self.update_filter_combos(stage_name)              

    def refresh_results_data(self):
        """Обновление данных результатов"""
        if self.current_stage:
            self.load_matches_for_stage(self.current_stage)
            self.load_results_table_for_stage(self.current_stage)
            QMessageBox.information(self, "Обновление", "Данные результатов обновлены")

    def show_results_filters(self):
        """Показать фильтры для результатов"""
        QMessageBox.information(self, "Фильтры", "Фильтры результатов (в разработке)")

    def export_results_to_pdf(self):
        """Экспорт результатов в PDF"""
        QMessageBox.information(self, "Экспорт", "Экспорт результатов в PDF (в разработке)")

    def move_to_next_field(self, current_row, current_col):
        """Переход к следующему полю ввода по Enter"""
        parties = self.parties_count
        all_score_1 = 0
        all_score_2 = 0
        all_score_1 = int(self.total_score1.text())
        all_score_2 = int(self.total_score2.text())

        # проверка крректности ввода счета
        score1 = self.score_edits_p1[current_col].text().strip()
        score2 = self.score_edits_p2[current_col].text().strip()

        if current_row == 1:  # Игрок 1
            if current_col < parties:
                # Переход к этой же партии игрока 2 (П1-1 → П1-2 → ...)
                self.score_edits_p2[current_col].setFocus()
        else:  # Игрок 2
            if current_col < parties - 1:
                if all_score_1 == math.ceil(parties / 2) or all_score_2 == math.ceil(parties / 2):
                    # После последней партии переходим на кнопку Сохранить
                    self.save_btn.setFocus()
                    self.save_match_result_compact()
                else:
                    is_valid, error = self.validate_score(score1, score2)
                    # Переход к следующей партии игрока 1 (П2-1 → П2-2 → ...)
                    if is_valid == True:
                        self.score_edits_p1[current_col + 1].setFocus()
                    else:
                        QMessageBox.information(self, "Ошибка", f"{error}")
            else:
                # После последней партии переходим на кнопку Сохранить
                self.save_btn.setFocus()
                # Автоматически сохраняем результат при нажатии Enter на последнем поле
                self.save_match_result_compact()

    def update_total_score(self):
        """Обновление общего счета и подсветка победителя с учетом статусов"""
        try:
            player1_wins = 0
            player2_wins = 0
            
            # Проверяем статусы игроков
            status1 = self.player1_status.currentText()
            status2 = self.player2_status.currentText()
            
            # Если есть неявка, отображаем технический результат
            if status1 != "Играет" and status2 == "Играет":
                self.total_score1.setText("П")
                self.total_score2.setText("В")
                self.player1_name.setStyleSheet("background-color: #FFB6C1;")
                self.player2_name.setStyleSheet("background-color: #90EE90;")
                return
            
            if status2 != "Играет" and status1 == "Играет":
                self.total_score1.setText("В")
                self.total_score2.setText("П")
                self.player1_name.setStyleSheet("background-color: #90EE90;")
                self.player2_name.setStyleSheet("background-color: #FFB6C1;")
                return
            
            if status1 != "Играет" and status2 != "Играет":
                self.total_score1.setText("П")
                self.total_score2.setText("П")
                self.player1_name.setStyleSheet("background-color: #FFB6C1;")
                self.player2_name.setStyleSheet("background-color: #FFB6C1;")
                return
            
            # Обычная игра - считаем победы по партиям
            for i in range(self.parties_count):
                score1 = self.score_edits_p1[i].text().strip()
                score2 = self.score_edits_p2[i].text().strip()
                
                if score1 and score2:
                    try:
                        s1 = int(score1)
                        s2 = int(score2)
                        if s1 > s2:
                            player1_wins += 1
                        elif s2 > s1:
                            player2_wins += 1
                    except ValueError:
                        pass
            
            # Обновляем общий счет
            self.total_score1.setText(str(player1_wins))
            self.total_score2.setText(str(player2_wins))
            
            # Определяем необходимое количество побед для победы в матче
            required_wins = self.parties_count // 2 + 1
            
            # Подсветка победителя
            if player1_wins >= required_wins:
                self.total_score1.setStyleSheet("background-color: #90EE90; font-weight: bold;")
                self.total_score2.setStyleSheet("")
                self.player1_name.setStyleSheet("background-color: #90EE90; font-weight: bold;")
                self.player2_name.setStyleSheet("background-color: #f0f0f0;")
            elif player2_wins >= required_wins:
                self.total_score2.setStyleSheet("background-color: #90EE90; font-weight: bold;")
                self.total_score1.setStyleSheet("")
                self.player2_name.setStyleSheet("background-color: #90EE90; font-weight: bold;")
                self.player1_name.setStyleSheet("background-color: #f0f0f0;")
            else:
                self.total_score1.setStyleSheet("")
                self.total_score2.setStyleSheet("")
                self.player1_name.setStyleSheet("background-color: #f0f0f0;")
                self.player2_name.setStyleSheet("background-color: #f0f0f0;")
                
        except Exception as e:
            print(f"Ошибка обновления счета: {e}")

    def validate_score(self, score1, score2):
        """
        Проверка корректности счета в партии
        Возвращает (is_valid, error_message)
        """
        # Проверка на пустые поля
        if not score1 or not score1.strip():
            return False, "Поле счета игрока 1 пустое"
        if not score2 or not score2.strip():
            return False, "Поле счета игрока 2 пустое"
        
        try:
            s1 = int(score1)
            s2 = int(score2)            
        except ValueError:
            return False, "Счет должен быть целым числом"
        
        # Проверка на отрицательные числа
        if s1 < 0 or s2 < 0:
            return False, "Счет не может быть отрицательным"
        
        # Проверка на слишком большие числа (более 30)
        if s1 > 30 or s2 > 30:
            reply = QMessageBox.question(self, "Подтверждение", 
                                        f"Введен необычно высокий счет: {s1}:{s2}\n"
                                        f"Это правильный счет?",
                                        QMessageBox.Yes | QMessageBox.No)
            if reply == QMessageBox.No:
                return False, "Пожалуйста, проверьте правильность ввода"
        
        # Если оба счета 0-9
        if s1 <= 9 and s2 <= 9:
            if s1 == 11 and s2 <= 9:
                return True, ""
            if s2 == 11 and s1 <= 9:
                return True, ""
            if s1 <= 9 and s2 <= 9:
                return False, f"При счете до 9 ничья не может быть {s1}:{s2}"
        
        # Если один из игроков набрал 11, а другой менее 9
        if s1 == 11 and s2 <= 9:
            return True, ""
        if s2 == 11 and s1 <= 9:
            return True, ""
        
        # Если счет 10 и более, разница должна быть 2 очка
        if s1 >= 10 and s2 >= 10:
            if abs(s1 - s2) == 2:
                return True, ""
            else:
                return False, f"При счете 10 и более разница должна быть 2 очка. Текущий счет: {s1}:{s2}"
        
        return True, ""

